module EG_PHY_MSLICE
  (
  a,
  b,
  c,
  ce,
  clk,
  d,
  mi,
  sr,
  fci,
  f,
  fx,
  q,
  fco,
  dpram_mode,
  dpram_di,
  dpram_we,
  dpram_waddr,
  dpram_wclk  
  );
  input [1:0] a,b,c,d,mi;
  input clk;                 //  [Template:Clock input.]
  input ce;                  //  [Template:Clock enable input.]
  input sr;                  //  [Template:DFF reset contrl.]
  input fci;                 //  [Template:carry input.]
  output [1:0] f;   //  [Template:LUT primary output.]
  output [1:0] fx;  //  [Template:LUT auxiliary output.]
  output [1:0] q;   //  [Template:Lslice output.]   
  output fco;                //  [Template:carry output.]
// dpram special interface  
  input dpram_mode;          //  [Template:Disram mode contrl output.]
  input [1:0] dpram_di;      //  [Template:Disram writes data output.]
  input dpram_we;            //  [Template:Disram writes enable output.]
  input dpram_wclk;          //  [Template:Disram writes clock output.]
  input [3:0]dpram_waddr;    //  [Template:Disram writes address output.]

wire [1:0] q_tmp;
buf (q[0],q_tmp[0]);
buf (q[1],q_tmp[1]);
      
tri1 [1:0] a,b,c,d,mi;
tri1 clk;
tri1 ce;
tri1 sr;
tri0 fci; 
tri0 dpram_mode;
tri0 [1:0] dpram_di;
tri0 dpram_we;
tri0 dpram_wclk;
tri0 [3:0]dpram_waddr;
   

parameter INIT_LUT0 = 16'h0000 ;   //  16'h0000~16'h1111.[Template:Lut4 initial value.  ]
parameter INIT_LUT1 = 16'h0000 ;   //  16'h0000~16'h1111.[Template:Lut4 initial value.  ]
parameter MODE = "LOGIC" ;         //  "LOGIC", "RIPPLE", "DPRAM".[Template:Mode select.]
parameter ALUTYPE = "";            
parameter MSFXMUX = "OFF" ;        //  "OFF", "ON".[Template:FX output enable.    ]
parameter GSR = "ENABLE" ;         //  "ENABLE", "DISABLE".[Template:Global reset.]
parameter TESTMODE = "OFF" ;       //  "OFF", "ON".[Template:Test mode.           ]
//parameter CEMUX = "1" ;        
